{"summary": "Probe PWT download URLs and check network access", "command": "python3 - <<'PY'
import sys, urllib.request
urls=[
 'https://www.rug.nl/ggdc/docs/pwt110.xlsx',
 'https://www.rug.nl/ggdc/docs/pwt110.xlsx?lang=en',
 'https://www.rug.nl/ggdc/productivity/pwt/pwt110.xlsx',
 'https://www.rug.nl/ggdc/productivity/pwt/pwt110/pwt110.xlsx'
]
for u in urls:
    try:
        with urllib.request.urlopen(u, timeout=20) as r:
            print(u,'->',r.status,r.getheader('Content-Type'),r.getheader('Content-Length'))
            break
    except Exception as e:
        print('fail',u,type(e).__name__,e)
