{"summary": "Look up variable definitions for rnna and rkna in PWT Legend", "command": "python3 - <<'PY'
import openpyxl
wb=openpyxl.load_workbook('pwt11_dataverse_554105.xlsx', read_only=True, data_only=True)
ws=wb['Legend']
# iterate until find rows containing rnna or rkna
found={}
for row in ws.iter_rows(values_only=True):
    if not row or row[0] is None: continue
    key=str(row[0]).strip() if row[0] else ''
    if key in ('rnna','rkna'):
        found[key]=row
        if len(found)==2:
            break
print('rnna:',found.get('rnna'))
print('rkna:',found.get('rkna'))
PY"}

