{"summary": "Scrape IMF WEO database page for downloadable XLS links", "command": "python3 - <<'PY'
import urllib.request, re
url='https://www.imf.org/en/Publications/WEO/weo-database/2025/April'
html=urllib.request.urlopen(url,timeout=30).read().decode('utf-8','ignore')
print('len',len(html))
# find links containing weodata or WEOApr
links=re.findall(r'href="([^"]+)"', html)
for l in links:
    if 'weodata' in l.lower() or 'weoapr' in l.lower() or 'weo' in l.lower() and ('all' in l.lower() or 'WEOApr' in l):
        if 'http' not in l:
            l='https://www.imf.org'+l
        if any(k in l.lower() for k in ['weoapr','weo','weodata']) and any(k in l.lower() for k in ['all','xls','xlsx','csv','ashx','zip']):
            print(l)
# more targeted regex for WEOApr.*all
for m in re.findall(r'(https?://[^\s"\']+WEO[^\s"\']+)', html):
    if 'weodata' in m.lower() or 'all' in m.lower():
        print('m',m)
PY"}

{"summary": "Fetch IMF WEO page with browser user-agent to bypass 403", "command": "python3 - <<'PY'
import urllib.request, re
url='https://www.imf.org/en/Publications/WEO/weo-database/2025/April'
req=urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
html=urllib.request.urlopen(req,timeout=30).read().decode('utf-8','ignore')
print('len',len(html))
# find potential weodata links
for l in re.findall(r'href="([^"]+)"', html):
    if 'weodata' in l.lower() and ('xls' in l.lower() or 'csv' in l.lower() or 'ashx' in l.lower() or 'zip' in l.lower()):
        if l.startswith('/'):
            l='https://www.imf.org'+l
        print(l)
# also look for WEOApr patterns
for m in re.findall(r'WEO[A-Za-z0-9]+all\.[a-z]+', html):
    print('file',m)
PY"}

